/* @autogenerated */
package net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.step;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.core.Response.ResponseBuilder;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.features.oauth.authentication.domain.ChallengesState;
import net.civeira.phylax.features.oauth.authentication.domain.exception.AuthenticationException;
import net.civeira.phylax.features.oauth.authentication.domain.exception.ConsentRequiredException;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.AuthorizeHtml;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.OidcStep;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.SecureHtmlBuilder;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepInput;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepOutcome;
import net.civeira.phylax.features.oauth.consent.application.GdprConsentUsecase;
import net.civeira.phylax.features.oauth.consent.application.TermsOfUseConsentUsecase;
import net.civeira.phylax.features.oauth.consent.domain.GdprConsentPurposeItem;
import net.civeira.phylax.features.oauth.consent.domain.TermsOfUseAcceptance;
import net.civeira.phylax.features.oauth.theme.domain.gateway.DecoratePageGateway;

/**
 * OIDC step for user consent handling.
 *
 * Handles the {@code step=consent} form submission and renders the consent form when
 * {@link ConsentRequiredException} is thrown by the login use case.
 *
 * Shows the first pending terms-of-use version and any pending GDPR purposes. On acceptance stores
 * both the terms acceptance and the GDPR purpose decisions before continuing the flow.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ConsentStep implements OidcStep {

  private final SecureHtmlBuilder securer;
  private final TermsOfUseConsentUsecase touUsecase;
  private final GdprConsentUsecase gdprUsecase;
  private final DecoratePageGateway decorator;

  @Override
  public AuthenticationChallenge challenge() {
    return AuthenticationChallenge.USE_CONSENT;
  }

  @Override
  public Class<? extends AuthenticationException> challengeException() {
    return ConsentRequiredException.class;
  }

  @Override
  public Set<String> stepNames() {
    return Set.of("consent");
  }

  @Override
  public Response paint(StepInput input, NewCookie preSession) {
    String username = input.currentUser().orElse("");
    return securer.secureHtmlResponse(buildForm(input, username, null).cookie(preSession));
  }

  @Override
  public Optional<StepOutcome> process(StepInput input) {
    if (!"consent".equals(input.step()) || input.currentUser().isEmpty()) {
      return Optional.empty();
    }
    String username = input.currentUser().get();
    String accept = AuthorizeHtml.first(input.getFormParams(), "accept");
    String consentId = AuthorizeHtml.first(input.getFormParams(), "consent");
    if (("on".equals(accept) || "accept".equals(accept)) && consentId != null
        && !consentId.isBlank()) {
      String consentText = AuthorizeHtml.first(input.getFormParams(), "conditions");
      touUsecase.storeAcceptedConsent(input.getRequest().getTenant(), username,
          input.getRequest().getAudiences(),
          new TermsOfUseAcceptance(consentId, consentText != null ? consentText : ""));
      storeGdprDecisions(input, username);
      ChallengesState state =
          input.getChallenges().orElseGet(() -> ChallengesState.empty(username));
      return Optional.of(
          new StepOutcome.Proceed(username, input.getClientDetails(), input.getRequest(), state));
    } else {
      return Optional
          .of(new StepOutcome.Render(securer.secureHtmlResponse(buildForm(input, username, ""))));
    }
  }

  private void storeGdprDecisions(StepInput input, String username) {
    List<GdprConsentPurposeItem> pending =
        gdprUsecase.pendingPurposes(input.getRequest().getTenant(), username);
    if (pending.isEmpty()) {
      return;
    }
    List<String> checked = input.getFormParams().getOrDefault("gdpr_purposes", List.of());
    Map<String, Boolean> decisions = new LinkedHashMap<>();
    for (GdprConsentPurposeItem purpose : pending) {
      decisions.put(purpose.uid(), checked.contains(purpose.key()));
    }
    gdprUsecase.storePurposeDecisions(input.getRequest().getTenant(), username, decisions, "", "");
  }

  private ResponseBuilder buildForm(StepInput input, String username, String msg) {
    List<TermsOfUseAcceptance> pending = touUsecase.getPendingConsent(
        input.getRequest().getTenant(), username, input.getRequest().getAudiences());
    if (pending.isEmpty()) {
      throw new IllegalStateException("Consent is not required now...");
    }
    TermsOfUseAcceptance term = pending.get(0);

    List<GdprConsentPurposeItem> purposes =
        gdprUsecase.pendingPurposes(input.getRequest().getTenant(), username);

    String js = securer.configureScripts(securer.addSign("sign"));

    String title = AuthorizeHtml.i18n(input.locale(), "consent.title");
    String error = AuthorizeHtml.i18n(input.locale(), "consent.error-format", msg);
    String help = AuthorizeHtml.i18n(input.locale(), "consent.help");
    String code = AuthorizeHtml.i18n(input.locale(), "consent.code");
    String send = AuthorizeHtml.i18n(input.locale(), "consent.send");
    String backLabel = AuthorizeHtml.i18n(input.locale(), "consent.back-label");
    String backText = AuthorizeHtml.i18n(input.locale(), "consent.back-text",
        "<input class=\"inline\" type=\"submit\" value=\"" + backLabel + "\" />");

    return Response.ok(decorator.getFullPage(input.tenant(), "Consent",
        js + "<h1>" + title + "</h1><p>" + help + "</p>"
            + (null == msg ? "" : "<p class=\"error\">" + error + "</p>") + "<form method=\"POST\">"
            + "<input type=\"hidden\" name=\"csid\" id=\"sign\" />"
            + "<input type=\"hidden\" name=\"step\" value=\"consent\" />" + "<label>" + code
            + "<textarea name=\"conditions\" readonly>" + term.text() + "</textarea>" + "</label>"
            + "<label>Aceptar: <input type=\"checkbox\" name=\"accept\" value=\"accept\" /></label>"
            + "<input type=\"hidden\" name=\"consent\" value=\"" + term.id() + "\" />"
            + renderGdprBlock(purposes)
            + "<input class=\"primary-button action-button\" type=\"submit\" value=\"" + send
            + "\" />" + "</form>" + "<form method=\"POST\">"
            + "<input type=\"hidden\" name=\"step\" value=\"start\" />" + "<p>" + backText + "</p>"
            + "</form>",
        input.locale())).type(AuthorizeHtml.TEXT_HTML);
  }

  private String renderGdprBlock(List<GdprConsentPurposeItem> purposes) {
    if (purposes.isEmpty()) {
      return "";
    }
    StringBuilder items = new StringBuilder();
    for (GdprConsentPurposeItem p : purposes) {
      String requiredMark = p.required() ? " <span class=\"required-marker\">*</span>" : "";
      items.append("<li class=\"scope-item\">").append("<label class=\"scope-label\">")
          .append("<input type=\"checkbox\" name=\"gdpr_purposes\" value=\"").append(p.key())
          .append("\" />").append("<strong>").append(p.title()).append(requiredMark)
          .append("</strong>").append("</label>")
          .append("<details class=\"scope-description\"><summary>Descripcion</summary><p>")
          .append(p.description()).append("</p></details>").append("</li>");
    }
    return "<section class=\"gdpr-purposes\">"
        + "<h3>Propósitos de tratamiento de datos (GDPR)</h3>" + "<ul class=\"scopes-list\">"
        + items + "</ul>" + "</section>";
  }
}
